@startuml

class Person {
  + personID : int
  + phoneNumber : string
  + researchKeywords : string[]
  + institutionCode : int
}

class ResearchInstitution {
  + institutionCode : int
  + name : string
}

class ScientificArticle {
  + DOI : string
  + title : string
  + authors : Person[]
  + authorPositions : int[]
}

interface PeerReviewedPaper extends ScientificArticle {
  + citationCount : int
  + reviewers : Person[]
}

interface TechnicalReport extends ScientificArticle {
  + publisher : ResearchInstitution
}

class Publisher {
  + name : string
}

class Journal {
  + journalName : string
  + impactFactor : float
  + publisher : Publisher
}

Person "1" -- "0..*" ScientificArticle : authors
ResearchInstitution "1" *-- "0..*" TechnicalReport : publishes
Publisher "1" *-- "0..*" Journal : publishes

PeerReviewedPaper --|> ScientificArticle
TechnicalReport --|> ScientificArticle

@enduml

